static int taglist_checkItem(tagListType *t)
{
	int i = 0;
	const char * const list[] = {
		"SUBSR_LICENSE",
		"SUBSR_LICENSE_DUE",
		"SUBSR_LICENSE_DUE_EXPIRE",
		"SUBSR_LICENSE_DUE_TIMER",
		"SERVICE_CARE_DUE",
		"SERVICE_CARE_DUE_EXPIRE",
		"SERVICE_CARE_DUE_TIMER",
		"SERVICE_CARE_NAME",
		"SERVICE_CARE_TYPE",
		"SERVICE_SFWAN",
		"SERVICE_SFWAN_CP",
		"SERVICE_SFWAN_CP_SUSPEND",
		"SERVICE_SFWAN_SERVER",
		"SERVICE_SFWAN_SUSPEND",
		"ADMIN_PASSWORD",
		"ADMIN_NAME",
		"ADMIN_LANONLY"
	};
    char portlan[64] = {0};



	for (i = 0; i < ARRAY_SIZE(list); i++) {
		if (exist_taglist(t, list[i])) {
            printf("Tag [%s] = %s\n", list[i], get_taglist(t, list[i]));
		}
	}

	for (i = 1; i <= 8; i++) {
        snprintf(portlan, sizeof(portlan), "EXTSW_PORT%d_LAN_LIST", i);
		if (exist_taglist(t, portlan)) {
            printf("Tag [%s] = %s\n", portlan, get_taglist(t, portlan));
		}
    }

	return 1;
}

static void taglist_traverse(tagListType *list)
{
    int i;
    int i_max;

    printf("Number of tags = %d\n", list->size);

    for (i = 0, i_max = list->size; i < i_max; i++)
    {
        printf("Tag[%s] = %s\n", list->item[i]->tag , list->item[i]->value);
    }
}

